css:
atom-pane.active .tab-bar .tab .title {
  -webkit-mask: linear-gradient(to left, rgba(0, 0, 0, 0), #000000 1em) no-repeat;
  -webkit-mask-position: -1em 0;
}
atom-pane.active .tab-bar .tab:not(:hover):not(.hover):nth-of-type(1) .close-icon {
  transform: none;
  -webkit-animation: initial;
}
atom-pane.active .tab-bar .tab:not(:hover):not(.hover):nth-of-type(1) .close-icon::before {
  font-family: Helvetica, Arial, sans-serif;
  content: "1";
  font-size: 12px;
  font-weight: bold;
  transform: none;
}
